import math, json, random

def orig(x):
    r = math.radians
    return 4*math.sin(x)*math.sin(r(60)-x)*math.sin(r(60)+x)

candidates = {
    "sin(3x)": lambda x: math.sin(3*x),
    "cos(3x)": lambda x: math.cos(3*x),
    "sin(2x)": lambda x: math.sin(2*x),
    "cos(2x)": lambda x: math.cos(2*x),
    "sin(x)": lambda x: math.sin(x),
    "cos(x)": lambda x: math.cos(x),
    "sin(x^3)": lambda x: math.sin(x**3),
    "-sin(3x)": lambda x: -math.sin(3*x),
}

random.seed(1)
pts = [random.uniform(-2*math.pi, 2*math.pi) for _ in range(500)]
pts += [math.radians(d) for d in range(-360, 361, 5)]

results = {}
for name, f in candidates.items():
    results[name] = max(abs(orig(x) - f(x)) for x in pts)

matches = [n for n, e in results.items() if e < 1e-9]
if len(matches) == 1:
    final = matches[0]
    print(json.dumps({
        "final_answer": final,
        "evidence": {"points_tested": len(pts), "max_abs_error": results[final]}
    }))
else:
    print("UNSUPPORTED")
